insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$agaricus-bozi-houba$q$,$q$Agaricus – „Boží houba“$q$,$q$Málo která přírodní houba stabilizuje imunitní systém tak účinně jako Agaricus. Tato houba má mnoho jmen. V překladu zní – brazilská mandlová houba nebo mandlová houba pro svou mandlovou vůni a chuť nebo sluneční houba Royal Sun Agaricus, protože miluje slunce. Roste na otevřených plochách v horskýc$q$,$q$<blockquote>
<p>Málo která přírodní houba stabilizuje imunitní systém tak účinně jako Agaricus.</p>
</blockquote>
<p>Tato houba má mnoho jmen. V překladu zní – brazilská mandlová houba nebo mandlová houba pro svou mandlovou vůni a chuť nebo sluneční houba Royal Sun Agaricus, protože miluje slunce. Roste na otevřených plochách v horských oblastech Piedade v nadmořské výšce asi 800 m za subtropických podmínek. Tato houba se stala známou zejména v Brazílii. Lidé, kteří ji konzumovali daleko <strong>méně trpěli degenerativními chorobami</strong>, jako jsou známky stárnutí, cukrovka a rakovina. V Brazílii je dokonce uctívána jako <strong>„Boží houba“.</strong></p>
<h3>Jak Agaricus blazei murrill ovlivňuje imunitní systém?</h3>
<p>Přírodní houba Agaricus blazei murrill reguluje celý<strong> imunitní systém</strong> , zejména při rakovině a <strong>autoimunitních</strong> onemocněních. Důvodem je to, že má extrémně vysoký obsah velmi účinných imunomodulátorů. Mandlová houba obsahuje mnoho polysacharidů s dlouhým řetězcem , beta-glukany. Jejich složitá chemická struktura vede ke stejně složitému způsobu působení. Stimulují mimo jiné oslabený imunitní systém, ale také zabraňují nebo regulují nadměrné imunitní reakce – tedy autoimunitní choroby.</p>
<h3>Zásadní houba v doplňkové terapii rakoviny</h3>
<p>Účinnost Agaricusu byla prokázána především u rakoviny břicha, tlustého střeva, plic, slinivky břišní, prostaty a jater a také u nádorů na mozku. Studie prokázaly, že tato léčivá houba má přímý účinek na rakovinné buňky: <strong>iniciuje apoptózu</strong> &#8211; buněčnou smrt nádorových buněk. <strong>Aktivuje také imunitní mechanismy, které jsou důležité pro obranu proti nádorům.</strong></p>
<p>Pokud je tvorba krve narušena<strong> po chemoterapii nebo radiační terapii</strong>, Agaricus podporuje regeneraci kostní dřeně. Působí proti vyčerpání v důsledku nedostatku erytrocytů nebo rostoucí imunitní nedostatečnosti v důsledku ztráty leukocytů. Kromě toho lze pomocí Agaricusu snížit dysfunkci sleziny, která se vyskytuje například u leukémie nebo lymfomu. Jako všechny adaptogeny má ochranný účinek na játra. Obecný stav pacientů s rakovinou lze tedy výrazně zlepšit.</p>
<h3>Agaricus blazei murrill má silné antioxidační vlastnosti</h3>
<p>V dnešní době je oxidační stres hlavním problémem při rozvoji mnoha nemocí: oxidační stres produkuje kouření, špatná výživa, znečištění životního prostředí, UV záření, zármutek, obavy a také chronický zánět. Výsledné látky poškozují naše tělesné buňky a náš genetický materiál, DNA. To vede k poškození kardiovaskulárního systému, kloubů, předčasnému stárnutí, alergiím nebo dokonce cukrovce. Studie prokázaly, že použití houby výrazně <strong>omezuje oxidační procesy.</strong></p>
<h3>Agaricus blazei murrill a dýchání</h3>
<p>Agaricus se s velkým úspěchem používá v léčbě všech chorob, které se projevují dechovou nedostatečností. Mohou to být různé druhy <strong>alergií, chronické záněty průdušek, CHOPN, astma</strong> a další. V posledních měsících se velmi osvědčil v<strong> doléčování následků <a href="https://anetabenediktova.cz/regenerace-po-covidu/">onemocnění Covid 19</a></strong>. Posiluje a regeneruje nejenom plíce, ale i celý imunitní systém.</p>

<blockquote>
<p><em>V jakém výrobku najdete:</em> kapsle <a href="https://serafinbyliny.cz/produkt/agaricus_104">Agaricus</a> s jitrocelem, kapsle <a href="https://serafinbyliny.cz/produkt/plice_103">Plíce</a> – regenerace, kapsle <a href="https://serafinbyliny.cz/produkt/pylergen_127">Pylergen</a>, <a href="https://serafinbyliny.cz/produkt/serafinkuv-detsky-sirup_234">Serafínkův</a> dětský sirup</p>
</blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/04/agaricus-2.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$]::text[],$q$published$q$,$q$2021-05-27T11:10:04+00:00$q$,$q$https://anetabenediktova.cz/agaricus-bozi-houba/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$polyporus-houba-pro-vasi-lymfu-a-imunitu$q$,$q$Polyporus – houba pro vaši lymfu a imunitu$q$,$q$Polyporus umbellatus je úžasná léčivá houba pro podporu imunitního systému a zároveň detoxikaci a harmonizaci lymfatického systému. Eliminuje zadržování vody v těle a podporuje proudění lymfy v lymfatických cévách a umí si poradit s celou řadou bakterií. Kde ji najdeme? Polyporus patří mezi dřevokaz$q$,$q$<blockquote>
<p>Polyporus umbellatus je úžasná léčivá houba pro podporu <strong>imunitního systému</strong> a zároveň detoxikaci a harmonizaci <strong>lymfatického systému</strong>. Eliminuje zadržování vody v těle a podporuje proudění lymfy v lymfatických cévách a umí si poradit s celou řadou <strong>bakterií.</strong></p>
</blockquote>
<h3>Kde ji najdeme?</h3>
<p>Polyporus patří mezi dřevokazné chorošovité houby, které můžeme najít na kořenech zdravých listnatých stromů, ale také na poraněných či mrtvých stromech a pařezech. Nejčastěji napadá duby, habry a buku. Plodnice Polyporu vyrůstá z třeně, který odstupuje od stromu a větví se na další „malé houbové nožky“. Na nich jsou pak drobné, pravidelné a dovnitř vmáčklé kloboučky, vytváří tak jakýsi trs. Díky tomu může mít celá plodnice i více než 50 cm v průměru. Polyporus roste v mírném pásmu v Severní Americe, Evropě i Asii. Je možné jej najít i v u nás, a to hlavně v Polabí, v jižních Čechách a na Moravě</p>
<h3>Polyporus a odvodnění</h3>
<p>Tato léčivá houba <strong>přirozeně odvodňuje</strong>, aniž by zvyšovala vylučování draslíku, tak jak to běžně dělají léky na odvodnění. Tímto principem je <strong>šetrná k srdci</strong>. V přírodním léčitelství se Polyporus používá na <strong>otoky</strong> způsobené špatnou funkcí lymfatického systému, žilní nedostatečností nebo srdeční nedostatečností.</p>
<p>Obsažené složky &#8211; ergosterol a mannitol &#8211; působí jako takzvaní <strong>antagonisté aldosteronu</strong>. Hormon <strong>aldosteron</strong> reguluje naši <strong>rovnováhu vody a elektrolytů</strong>. Zabraňuje tomu, aby ledviny vylučovaly příliš mnoho vody. Aktivní složky léčivé houby snižují účinek aldosteronu a následně tím snižují otoky.</p>
<h3>Polyporus a lymfatický systém</h3>
<p>Většina toxinů je transportováno z tělních tkání pomocí lymfy. Ty jsou následně vylučovány játry nebo ledvinami. Lymfatický systém hraje důležitou roli také při celkové imunitě organismu. Přetížení lymfatického systému vede k přetížení organismu odpadními látkami a tím k další zátěži imunitního systému. Léčivá houba Polyporus celkově harmonizuje <strong>lymfatický systém, podporuje vylučování odpadních látek a posiluje imunitní systém</strong>. Je to skvělá houba na <strong>odstranění kyselých usazenin z kloubů a svalů.</strong></p>
<h3>Polyporus a močový měchýř</h3>
<p>Staré tradice říkají, že Polyporus „osvobozuje močový měchýř“. Působí močopudně a je proto prospěšný při <strong>problémech s močením</strong>, dysfunkci močového měchýře a zejména při zadržování moči, které mohou mít různé příčiny. U mužů je nejčastější příčinou <strong>zvětšená prostata</strong>.</p>
<p>U žen může být příčinou <strong>pokles ženských orgánů</strong>, zejména dělohy, ale také samotného močového měchýře. Další možnou příčinou problémů s vyprazdňováním močového měchýře může být <strong>neuropatie v souvislosti s cukrovkou.</strong> U těchto onemocnění působí léčivé houby močopudně a posilují funkci močového měchýře. Polyporus také zajišťuje vyplavování patogenů z močových cest, což <strong>snižuje riziko infekce.</strong></p>
<h3>Polyporus a bakterie</h3>
<p>Polyporus má silný <strong>antibakteriální účinek</strong>. Účinně působí proti bakteriím zejména v urogenitálním systému, ale také proti různým typům parazitů a proti interbuněčným parazitům jako jsou např. chlamýdie. Je vhodný na celkovou podporu <strong>imunity, při zánětech močového ústrojí, gynekologických zánětech, angínách a zánětech v oblasti lymfatického systému</strong>.</p>
<h3>Polyporus a vlasy, kůže</h3>
<p>Polyporus má pozitivní vliv na pokožku a vlasy. To úzce souvisí s jeho detoxikačním účinkem. Léčivá houba odstraňuje odpadní produkty a toxiny, jak je popsáno, ledvinami a lymfatickým systémem . Ve skutečnosti byly v léčivé houbě také nalezeny určité přísady, které stimulují růst vlasů , tzv. Polyporusteron a acetosyringon.</p>
<p>Na kvalitu vlasů a kůže přispívají také mikroživiny <strong>zinek, železo, měď a biotin</strong> obsažené v Polyporu. Vzhledem k tomu, že vypadávání vlasů může mít různé příčiny, nabízí se skvělá <strong>kombinace hub Cordyceps, Polyporus a Reishi.</strong> Tato kombinace se osvědčila v terapeutické praxi při podpoře kvality vlasů, kůže a harmonizaci hormonálního systému.</p>

<blockquote>
<p><em>V jakém výrobku houbu najdete?</em> kapsle <a href="https://www.serafinbyliny.cz/produkty-ochrance-prirodni-kapsle-detail-1252">Ochránce</a>, kapsle <a href="https://www.serafinbyliny.cz/produkty-klouby-prirodni-kapsle-detail-3876">Klouby</a>, kapsle <a href="https://www.serafinbyliny.cz/produkty-paravit-prirodni-kapsle-detail-1913">Paravit</a>, kapsle <a href="https://www.serafinbyliny.cz/produkty-polyporus-s-jitrocelem-40-polysacharidu-detail-17269">Polyporus</a> s jitrocelem</p>
</blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/05/polyporus-umbellatus.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$]::text[],$q$published$q$,$q$2021-05-13T14:07:02+00:00$q$,$q$https://anetabenediktova.cz/polyporus-houba-pro-vasi-lymfu-a-imunitu/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$stetka-a-borelioza$q$,$q$Štětka a borelióza$q$,$q$Štětka planá patří mezi méně známé léčivé rostliny. Účinky její a jejích „sester“ začínají přicházet do popředí zájmu hlavně v souvislosti s rozšířením Lymské boreliózy. Štětka planá je řazena do čeledi štětkovitých, kam patří i Štětka lesní a Štětka soukenická. Přívlastek “soukenická” byl odvozen o$q$,$q$<blockquote>
<p>Štětka planá patří mezi méně známé léčivé rostliny. Účinky její a jejích „sester“ začínají přicházet do popředí zájmu hlavně v souvislosti s rozšířením Lymské boreliózy.</p>
</blockquote>
<p><strong>Štětka planá</strong> je řazena do čeledi štětkovitých, kam patří i <strong>Štětka lesní a Štětka soukenická.</strong> Přívlastek “soukenická” byl odvozen od jejího způsobu použití. Štětka soukenická byla dříve pěstovaná pro suchá květenství, kterými se česala příze. Jako zajímavost lze zmínit, že za tímto účelem byla dovezena již kolem roku 1700 do anglických kolonií v Severní Americe, kde ovšem záhy zplaněla a stala se obtížným plevelem. Pro stejné účely byla používána i štětka laločnatá.</p>
<blockquote>
<p>Všechny druhy Štětky, tedy planá, lesní i soukenická mají jako léčivé byliny téměř stejné působení.</p>
</blockquote>
<p>Pokud při procházkách přírodou na tuto bylinu narazíme, jistě si ji všimneme. S oblibou roste na vlhčích místech, jako jsou například břehy řek, můžeme ji najít i na rumištích nebo okrajích skládek. Často dorůstá až výšky dvou metrů a na vrcholu je zakončena výrazným světle fialovým až bílým květenstvím. Suché květy svým tvarem podobné štětce se často používají jako domácí dekorace.</p>
<p>Štětka obsahuje řadu přírodních látek, z nichž je možné zmínit třísloviny, flavonoidy, minimální množství alkaloidů, minerální látky, silice nebo pryskyřice. Jako léčivá droga se z ní používá zejména kořen nebo také nať. V lidovém léčitelství se většinou doporučuje jako <strong>čaj ve formě odvaru</strong>, ale dá se také zpracovat <strong>formou tinktury</strong>.</p>
<h3>Léčebné užití</h3>
<p>V přírodním léčitelství je Štětka s oblibou využívána jako doplněk léčby<strong> revmatických nemocí a dny</strong>. Používá se všude tam, kde je potřeba <strong>zmírnit otoky</strong> – odvodnit, nebo při nemocech <strong>gastrointestinálního traktu</strong>. Působí velmi dobře i při virových onemocněních jako je třeba <strong>opar</strong>.</p>
<p>Štětka lesní je také jednou z léčivých rostlin, o kterých odborníci uvažují jako o pomocníku při léčbě <strong>Lymské boreliózy. </strong></p>
<p>S úspěchem se používá se i zevně při různých kožních onemocněních, jako například rozpraskané <strong>pokožka nebo lišej</strong>. V tomto případě se používají obklady z odvaru z kořene.</p>
<h3>Štětka a borelióza</h3>
<p>V posledních letech je Štětka spojována zejména s Lymskou boreliózou. Podnětem byly výzkumy Stephen Harrod Buhnera a jeho kniha Borelióza.</p>
<p>Kořen Štětky a tinktura z něj, která se v případě boreliózy používá, není antibiotikum, ale  dokáže změnit prostředí těla tak, aby ono <strong>samo dokázalo zlikvidovat bakterii boreliózy</strong>. Svaly a pojivová tkáň jsou stimulovány k vyloučení těchto spirochét do krevního oběhu a tělo je pak schopno s ní bojovat <strong>pomocí imunity</strong>. Může být prospěšný u lidí, u kterých antibiotika Lymskou boreliózu nevyřešily úplně.</p>
<p>Spirochéty borelie jsou ve tvaru spirály, jako <strong>vrták se pak zavrtávají hluboko do tkání</strong> jako jsou klouby nebo kosti, pak se tedy vyskytují hluboko uvnitř těla mimo dosah léčiv a antibiotik a <strong>mimo dosah imunitního systému</strong>. Připodobňuje se to například opouzdřené cystě. Pokud se odtud borelie díky léčbě tinkturou ze Štětky dostanou do krevního oběhu, imunitní systém je zaregistruje a může je zabít.</p>
<p>Štětku v případě léčby boreliózy je dobré <strong>kombinovat s přírodními houbami</strong> jako je zejména <strong>Polyporus</strong>, který vyživuje prostřednictvím přirozených betaglukanů imunitní systém. Touto podporou si bílé krvinky lépe s uvolněnými spirochéty borelie poradí.</p>
<p>Základem dobré imunity je střevo. Pokud se k léčbě přidá i <strong>extrakt z Ořešáku královského</strong>, který má antiparazitální účinky ve střevě, tak se zvýší celkový účinek přírodní léčby Lymské boreliózy.</p>
<p>Štětka je krásná bylina při svém květu, nádherná dekorace po usušení a významná bylina při léčení. Objevte sílu přírody kolem nás!</p>

<blockquote>
<h3>Tipy:</h3>
<p><strong>Kůra na léčbu chronické Lymské boreliózy:</strong> střídejte po dni čaje <a href="https://www.serafinbyliny.cz/produkty-klouby-bylinny-caj-sypany-detail-194">Klouby</a> a <a href="https://www.serafinbyliny.cz/produkty-imunita-bylinny-caj-sypany-detail-191">Imunita</a>. K tomu každý den užívejte tinkturu <a href="https://www.serafinbyliny.cz/produkty-stetka-tinktura-z-bylin-detail-18240">Štětka</a> a kapsle <a href="https://www.serafinbyliny.cz/produkty-paravit-prirodni-kapsle-detail-1913">Paravit</a> ( s obsahem Polyporu a Ořešáku)</p>
<p>Při akutním přisátí klíštěte &#8211; po vyjmutí klíštěte místo potírejte <a href="https://anetabenediktova.cz/draci-krev-amazonsky-zazrak-pro-vas/">Dračí krví</a> a Dračí krev společně s <a href="https://www.serafinbyliny.cz/produkty-polyporus-s-jitrocelem-40-polysacharidu-detail-17269">Polyporusem</a> užívejte i vnitřně po dobu minimálně 3 týdnů.</p>
</blockquote>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/05/image.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$,$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2021-05-07T09:09:01+00:00$q$,$q$https://anetabenediktova.cz/stetka-a-borelioza/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$reishi-houba-zdravi-a-dlouhovekosti$q$,$q$Reishi – houba zdraví a dlouhověkosti$q$,$q$Říká se, že český národ je národem sběračů hub. Houby rádi sbíráme a konzumujeme v nejrůznějších pokrmech. Málokdo ale ví, že houby jsou nejenom výtečným pokrmem, ale také velmi silným léčivem pro různé neduhy našeho těla. Jedná se zejména o vzácnější druhy hub, a také o houby, které by běžný houbař$q$,$q$<blockquote>
<p>Říká se, že český národ je národem sběračů hub. Houby rádi sbíráme a konzumujeme v nejrůznějších pokrmech. Málokdo ale ví, že houby jsou nejenom výtečným pokrmem, ale také velmi silným léčivem pro různé neduhy našeho těla.</p>
</blockquote>
<p>Jedná se zejména o vzácnější druhy hub, a také o houby, které by běžný houbař asi z lesa domů k přípravě chutné večeře nepřinesl.</p>
<p>Podívejme se na jednu z nich, která nese honosný název <strong>Lesklokorka</strong>. Její název odráží její vzezření. Tato dřevokazná houba má lesklé, jakoby nalakované plodnice. Lesklokorek je několik druhů. V našich lesích se vyskytuje <strong>Lesklokorka jehličnatá</strong>, která má také léčebné účinky, nicméně silnější má <strong>Lesklokorka lesklá</strong>, jejíž původní domovinou je jihovýchodní Asie.</p>
<blockquote>
<p>Lesklokorka lesklá nebo-li  Reishi  je léčivá  houba, kterou tradiční čínská medicína využívá pro léčbu různých onemocnění již několik tisíc let. Houba je natolik účinná, že byla původně určena jen pro léčbu císaře a jeho rodiny. Říkali jí „houba dlouhověkosti“.</p>
</blockquote>
<h3>Jak působí?</h3>
<p>Zkoumání blahodárných účinků Reishi se věnují vědečtí pracovníci na celém světě. Reishi dokáže stimulovat a upravovat <strong>aktivitu imunitního systému</strong>. Jako silný antioxidant umí <strong>zpomalovat stárnutí</strong>. Také reguluje hladinu <strong>cholesterolu</strong> v krvi, podává se i u <strong><a href="https://anetabenediktova.cz/zazracny-bodlak-a-nemoci-jater/">steatózy jater</a>.</strong>  Působí jako životabudič, zvyšuje<strong> fyzickou a psychickou kondici</strong>. Reishi umí tlumit i rozvoj <strong>autoimunitních</strong> <strong>onemocnění</strong> např. u revmatoidní artritidy a velmi významně u autoimunitních chorob<strong> štítné žlázy</strong>. Má silné protirakovinné působení a je vhodná i jako doplněk při chemoterapii či ozařování.</p>
<h3>Reishi a alergie</h3>
<p>V neposlední řadě bylo též prokázáno, že Reishi dokáže velmi významně <strong>ovlivnit alergické reakce</strong> v organismu.  Ukazuje se, že Reishi má silné protialergické účinky. Jedna ze studií dokládá, že <strong>snižuje uvolnění histaminu</strong> z imunitních buněk hrajících úlohu v alergických reakcích. Také bylo doloženo, že v průběhu jejího podávání dochází ke snížení astmatických a kožních projevů u alergií.</p>
<h3>Sušená nebo koncentrát</h3>
<p>Sušená forma hub pro léčebné účely není tak účinná, jelikož organismus si z této formy nedokáže vzít dostatečné množství léčebných látek.<strong> Velmi účinný je koncentrát &#8211; extrakt</strong>, jehož vstřebatelnost pro organismus je velmi vysoká. Koncentrát vzniká luhováním houby v luhovacím mediu, kterým je nejčastěji voda. Silný výluh, který obsahuje koncentrovaný komplex účinných látek obsažených v houbě je speciální technologií vysušen na prášek. Tento prášek se pak dávkuje do jednotlivých kapslí.</p>
<h3>Kombinace hub</h3>
<p>Pro zvýšení blahodárných účinků přírodních hub se používá vzájemná kombinace dvou až tří druhů. Houby je také možné kombinovat s bylinami i s vitamíny a minerály.</p>
<p>Skvělou vlastností přírodních hub je, že na ně nevznikají reakce a působí synergicky s ostatními přírodními produkty.</p>
<p>Nyní už víte jaké poklady skrývají naše lesy!</p>

<blockquote>
<p><em>V jakém výrobku najdete:</em> kapsle <a href="https://www.serafinbyliny.cz/produkty-reishi-s-jitrocelem-a-zinkem-40-polysacharidu-detail-17268">Reishi</a> s jitrocelem a zinkem, kapsle <a href="https://www.serafinbyliny.cz/produkty-stitna-zlaza-prirodni-kapsle-detail-4848">Štítná žláza</a>, Serafínkův <a href="https://www.serafinbyliny.cz/produkty-detsky-sirup-serafinkuv-detail-10146">dětský sirup</a></p>
</blockquote>
<p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/05/medidinalni-houby.jpg$q$,$q$Byliny a houby$q$,array[$q$Bylinky$q$]::text[],$q$published$q$,$q$2021-05-06T12:20:13+00:00$q$,$q$https://anetabenediktova.cz/reishi-houba-zdravi-a-dlouhovekosti/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$regenerace-po-covidu$q$,$q$Regenerace po covidu$q$,$q$Silná únava, potíže s dýcháním, alergie, špatné vidění, ekzém, bolesti ledvin, bolesti kloubů. To jsou jen některé z obtíží, které mi popisují lidé, kteří prodělali infekci Covidem 19. Nejsem lékař, nejsem epidemiolog ani virolog, takže neumím úplně odborně říci a popsat následky infekce virem Covid$q$,$q$<blockquote>
<p><strong>Silná únava, potíže s dýcháním, alergie, špatné vidění, ekzém, bolesti ledvin, bolesti kloubů</strong>. To jsou jen některé z obtíží, které mi popisují lidé, kteří prodělali infekci Covidem 19.</p>
</blockquote>
<p>Nejsem lékař, nejsem epidemiolog ani virolog, takže neumím úplně odborně říci a popsat následky infekce virem Covid 19. Nicméně si myslím, že ani většina odborníků to úplně neumí, jelikož se jedná o velmi <strong>specifický vir, který se chová mírně řečeno nestandardně.</strong> Je vidět, že i lékařská obec sbírá zkušenosti, stejně jako sbíráme zkušenosti my, kteří se zabýváme celostním přístupem a přírodní léčbou.</p>
<p>Pozoruji, že mi přichází lidé většinou s velkým <strong>únavovým syndromem a poruchami dechu</strong>. Někdy se k tomu přidávají i <strong>bolesti ledvin.</strong></p>
<p>Pokud si udělám svoji diagnostiku, tak většinou vidím celkově<strong> vyčerpaný imunitní systém</strong>, <strong>lymfatický systém</strong> a špatně fungující <strong>plíce s průduškami</strong>. V tomto případě velmi dobře funguje přírodní kůra, která obsahuje bylinné čaje zaměřené na podporu fungování imunitního systému a k tomu přípravek s obsahem houby:</p>
<h3>Agaricus blazei Murrill</h3>
<p>Skvělá léčivá houba s českým názvem <strong>Žampion mandlový</strong> ( Agaricus blazei Murrill ) umí <strong>modulovat imunitní systém</strong> tak, aby on sám si uměl poradit s nezvanými hosty jako jsou <strong>viry, bakterie, plísně</strong>. Svým specifickým působením chrání lidskou DNA, takže se jeví i jako vhodný přírodní přípravek na užívání <strong>před a po očkování</strong>.</p>
<p>Žampion mandlový má ale také celou řadu dalších účinků. Jeho složení jej předurčuje jako skvělý přípravek <strong>při alergiích, astmatu, chronických zánětech plic a průdušek a dalších onemocnění plic</strong>.</p>
<p>V rámci přírodní medicíny se používá k <strong>regeneraci jater, slinivky, při diabetu</strong> anebo jako podpůrná léčba při rakovinném onemocnění.</p>
<p>Sám o sobě funguje skvěle. Pokud se však <strong>šikovně spojí</strong> s dalšími <strong>&#8222;přírodními bojovníky&#8220;</strong>, jako je třeba <strong>Vilcacora</strong> (kočičí dráp), <strong>Jitrocel</strong> kopinatý nebo přírodní vitamín C- <strong>Camu camu</strong>, tak jeho účinky jsou několikanásobně větší.</p>
<p><img fetchpriority="high" src="https://anetabenediktova.cz/wp-content/uploads/2021/04/agaricus-2-1024x682.jpg" alt="" /></p>
<p>Přírodní léčivé houby se vyznačují jednou významnou výhodou, a to je to, že se velmi dobře snáší s dalšími typy léčby zejména s konvenčními medicínskými přípravky. <strong>Nemají vedlejší účinky</strong>, nebývají na ně reakce. Jediné, co může člověk pociťovat je řidší stolice, a to pouze ve vyšších dávkách léčivých hub.</p>
<p>Pokud však budete vybírat přípravek s obsahem Agaricusu či jiné přírodní houby vždy dejte pozor na to, <strong>aby byl ve formě extraktu, koncentrátu</strong>. Ten totiž vaše tělo velmi dobře zpracuje. Namletou sušenou houbu v kapsli ne.</p>
<p>Doporučuji tedy kapsle <strong>Plíce s </strong>kvalitním extraktem<strong> z Agaricusu, </strong>extraktem<strong> z Vilcacory, Jitrocele, Camu camu a se zinkem </strong>v dobře vstřebatelné formě<strong>.</strong></p>

<blockquote>
<p><strong>Můj tip na regeneraci po covidu:</strong> užívejte čaj <a href="https://www.serafinbyliny.cz/produkty-imunita-bylinny-caj-sypany-detail-191">Imunita</a> a k tomu kapsle <a href="https://www.serafinbyliny.cz/produkty-plice-regenerace-detail-18027">Plíce</a></p>
</blockquote>

<p><strong>Druhým typem osob</strong>, kteří si stěžují na postcovidové problémy jsou lidé, kteří trpí nejenom únavou a problémy s dechem, ale <strong>přidávají se jim i problémy s trávením, popřípadě kožní obtíže.</strong> Podle mých pozorování to jsou nejčastěji lidé, kteří dříve trpěli nějakou formou virového onemocnění jako jsou třeba opary či lidé, kteří prodělali mononukleózu. Bylo totiž zjištěno, že Covid 19 aktivuje v organismu skryté viry, zejména EB virus. Více se dočtete v <a href="https://anetabenediktova.cz/jatra-a-virus/">tomto článku</a>.</p>
<p>I zde se velmi dobře uplatní náš známý <strong>Agaricus</strong>, ale je vhodné k němu přidat i zázrak z amazonského pralesa, přesněji řečeno z Ekvádorské džungle s názvem <strong>Dračí krev.</strong></p>
<p>Více o jejích účincích se můžete dočíst v mém starším článku <a href="https://anetabenediktova.cz/draci-krev-amazonsky-zazrak-pro-vas/">zde</a>. V souvislosti s tímto tématem zdůrazňuji, že to je přírodní látka, která velmi úspěšně působí proti virům včetně EB viru.</p>
<blockquote>
<p><strong>Můj tip II. na regeneraci po covidu</strong>: užívejte střídavě po dni čaje <a href="https://www.serafinbyliny.cz/produkty-imunita-bylinny-caj-sypany-detail-191">Imunita</a> a <a href="https://www.serafinbyliny.cz/produkty-jatra-bylinny-caj-sypany-detail-192">Játra</a>. K tomu každý den kapsle <a href="https://www.serafinbyliny.cz/produkty-plice-regenerace-detail-18027">Plíce</a> a kapky <a href="https://www.serafinbyliny.cz/produkty-draci-krev-detail-11826">Dračí krev</a></p>
</blockquote>
<p>Všichni si dozajista přejeme, aby toto těžké období poznamenané pandemií Covid 19 bylo již za námi, aby se z něj stala historie naší planety. Důležité však je, jak z tohoto boje vyjdeme. Jestli jako vítězové, poražení či jako zranění.</p>
<p>Zatím se zdá, že pomaličku začínáme vítězit, jen je důležité, aby nám nezůstala trvalá zranění, která by nám ztížila náš další život. Proto si myslím, že by každý měl dát svému tělu šanci na dostatečnou léčbu a regeneraci. Příroda je zde pro nás!</p>$q$,$q$https://anetabenediktova.cz/wp-content/uploads/2021/04/plice.jpg$q$,$q$Přírodní léčba$q$,array[$q$Nemoci přírodní léčba$q$]::text[],$q$published$q$,$q$2021-04-17T12:33:04+00:00$q$,$q$https://anetabenediktova.cz/regenerace-po-covidu/$q$) on conflict (slug) do nothing;
insert into public.posts (slug,title,excerpt,content,cover_image,category,tags,status,published_at,legacy_url) values ($q$stitna-zlaza-nas-stit-pred-zevnim-svetem$q$,$q$Štítná žláza – náš štít před zevním světem$q$,$q$Poruchy funkce štítné žlázy, a to zejména její autoimunitní zánět nabývá v populaci nebývalý nárůst. Jak štítná žláza funguje a jak jí můžeme pomoci přírodní cestou? Štítná žláza je umístěna dole na krku před hrtanem a je motýlovitého tvaru. Jejím úkolem je shromažďovat z krve jód k výrobě dvou horm$q$,$q$<p>Poruchy funkce štítné žlázy, a to zejména její <strong>autoimunitní zánět</strong> nabývá v populaci nebývalý nárůst. Jak štítná žláza funguje a jak jí můžeme pomoci přírodní cestou?</p>
<p>Štítná žláza je umístěna dole na krku před hrtanem a je motýlovitého tvaru. Jejím úkolem je <strong>shromažďovat z krve jód k výrobě dvou hormonů &#8211; thyroxinu a trijodthyroxinu</strong>, které regulují spotřebu energie doslova ve všech orgánech i ve všech buňkách těla. Je to jeden z nejdůležitějších regulačních orgánů, který se podílí na mnoha funkcích těla.</p>
<h2>Jak funguje štítná žláza</h2>
<p>Štítná žláza se podílí na celkovém <strong>vývoji, růstu, termoregulaci, látkové výměně, i fungování jiných žláz</strong> s vnitřní sekrecí. Je to<strong> nárazník našich emocí a stresů.</strong> Funkce štítné žlázy a jejich hormonů je velmi jemný a přesný řetězec reakcí v organismu, který začíná v mozku. Podvěsek mozkový vysílá speciální hormon, který aktivuje vznik hormonů štítné žlázy.</p>
<p>Pro správné fungování těla je nutné, aby na vyplavené hormony štítné žlázy dostatečně reagovaly receptory buněk, které mají vykonat příslušnou reakci v těle. Pokud někde na této cestě dojde k problému, vzniká onemocnění štítné žlázy, jehož nejčastějším projevem je <strong>autoimunitní zánět.</strong></p>
<h2>Autoimunitní zánět</h2>
<p>Autoimunitní onemocnění znamená, že imunitní systém začne vytvářet protilátky proti vlastnímu tělu a vždy je někam nasměruje. V tomto případě je nasměruje proti štítné žláze.</p>
<p>Štítná žláza spolupracuje s ostatními žlázami s vnitřní sekrecí, a to v linii <strong>hypofýza – štítná žláza – nadledvinky­ – vaječníky</strong>. Jestliže v této linii dochází trvale k přetížení, odráží se to právě na jejím zdraví.</p>
<p>Častými spouštěcími faktory jsou trvalé <strong>gynekologické záněty</strong> způsobné bakteriemi a parazity, <strong>hormonální substituce</strong>, trvalé přetížení slinivky nevhodnou stravou, dlouhodobá léčba kortikoidy, ale hlavním spouštěcím mechanismem je <strong>chronický stres.</strong></p>
<h2>Co dělá stres s tělem</h2>
<p>Pokud budeme hovořit o stresu – dlouhodobém psychickém vypětí, tak musíme hovořit o malém orgánu v našem <strong>mozku – hypofýze.</strong> Hypofýza patří do tzv. limbického mozku. Limbický mozek je první část našeho těla, která reaguje na impuls nebezpečí – na stres. Při takovém impulsu okamžitě vyburcuje tvorbu <strong>stresových hormonů v nadledvinkách.</strong> Ty nás mají chránit a připravit tělo na možnost reakce<strong> „boj nebo útěk&#8220;.</strong> Nabudí naše svaly, aktivují kardiovaskulární systém. Naproti tomu se omezí funkce trávicího traktu a zejména imunitního systému tak, aby tělo mělo dostatek energie stresovou situaci zvládnout.</p>
<p>Pokud našemu limbickému mozku stabilně dáváme impuls, že jsme v ohrožení ( bojíme se o děti, bojíme se o práci, máme strach z nemoci…), tak stabilně aktivuje obranný systém a produkuje velké množství stresových hormonů.</p>
<p>Celá tato činnost je prováděna na úkor trávení, imunitního systému, ale i funkce štítné žlázy a ostatních žláz s vnitřní sekrecí. Po uplynutí několika let takové vnitřní disharmonie se v organismu začnou projevovat problémy spojené zejména s orgány, které jsou při stresových reakcích omezovány. Velmi často dochází právě k autoimunitnímu zánětu štítné žlázy, kdy si začne tělo vyrábět protilátky proti tomuto orgánu.</p>
<p><img src="https://www.serafinbyliny.cz/ew/ew_images/image_of_object?ObjectIdentifier=pli:bf01678a-9fb0-4a6a-ad71-cddf5edc43e5&amp;Filter=042cdaac-4610-40de-a462-c4d4435cec81&amp;ImageIndex=1" alt="Image 1" /></p>
<h2>Léčba autoimunitního zánětu</h2>
<p>Základem léčby autoimunitního onemocnění štítné žlázy je <strong>uvolnění, relaxace.</strong> Výborně pomáhají různé techniky na uvolnění adrenalinu – <strong>běh, nordic walking , tanec, power jóga.</strong> <strong>Nezapomeňte zpívat!</strong> Můžete zpívat co vás napadne, velmi účinný je však zpěv mantry „óm“. <strong>Zpěv otevírá energetické centrum štítné žlázy.</strong> Pokud zpěv nepomáhá a stále cítíte přetlak v oblasti krku, prostě křičte. Nadechněte se a křičte z plných plic třeba v lese nebo v autě. Úleva nastane okamžitě.<strong> Přestaňte se bát a říkejte co cítíte!</strong></p>
<h2>Byliny – účinný pomocník</h2>
<p>Z bylinné říše můžeme zmínit třeba Chaluhu bublinatou, Šalvěj lékařskou, Srdečník obecný či Karbinec evropský</p>
<p>Štítná žláza pro svojí funkci nutně potřebuje <strong>jód</strong>. Ten najdete v bylinném čaji <strong>Štítná žláza snížená </strong>nebo v přírodních kapslích<strong> Kelp</strong></p>
<p>Dalším nutným prvkem je <strong>Selen. </strong>Hodně Selenu obsahují medicinální houby obsažené v přírodních kapslích <strong>Štítná žláza.</strong> Mimo to také umí snížit autoimunitní zánět a dostat váš imunitní systém do klidu. Klid vám  navodí přírodní <strong>kapsle <a href="https://www.serafinbyliny.cz/produkty-pohoda-prirodni-kapsle-detail-1255">Pohoda</a>.</strong></p>
<p>Velmi důležitou bylinou při léčbě autoimunitního zánětu štítné žlázy je tinktura z <strong>pupenů Černého jeřábu, </strong>která umí celkově harmonizovat funkci štítné žlázy.</p>
<blockquote>
<p><strong>Můj tip:</strong></p>
<p><strong>Autoimunitní zánět:</strong> pijte střídavě po dni čaje <a href="https://www.serafinbyliny.cz/produkty-stitna-zlaza-snizena-bylinny-caj-sypany-detail-212">Štítná žláza snížená</a> a <a href="https://www.serafinbyliny.cz/produkty-antistres-bylinny-caj-sypany-detail-181">Antistres</a>. K tomu denně užívejte kapsle <a href="https://www.serafinbyliny.cz/produkty-stitna-zlaza-prirodni-kapsle-detail-4848">Štítná žláza</a> a tinkturu z pupenů <a href="https://www.serafinbyliny.cz/produkty-cerny-jerab-tinktura-z-pupenu-detail-269">Černý jeřáb</a></p>
<p><strong>Uzlíky na štítné žláze:</strong> pijte střídavě po dni čaje <a href="https://www.serafinbyliny.cz/produkty-stitna-zlaza-snizena-bylinny-caj-sypany-detail-212">Štítná žláza snížená</a> a <a href="https://www.serafinbyliny.cz/produkty-antistres-bylinny-caj-sypany-detail-181">Antistres</a>. K tomu denně užívejte kapsle <a href="https://www.serafinbyliny.cz/produkty-stitna-zlaza-prirodni-kapsle-detail-4848">Štítná žláza</a> a kapsle <a href="https://www.serafinbyliny.cz/produkty-vilcacora-prirodni-kapsle-detail-1260">Vilcacora</a>.</p>
<p>Velmi pomáhá cílená meditace: <a href="https://anetabenediktova.cz/predvelikonocni-postni-meditace-ii-tyden/">zde</a></p>
</blockquote>
<p>
<p>Přestaňte svojí štítnou žlázu léčit, začněte jí uzdravovat!</p>
